import torch
from torch import nn
class TwoOutputs(nn.Module):
    def __init__(self):
        super().__init__()
        self.projection = nn.Linear(3,2)
    def forward(self, features):
        return self.projection(features)
example = TwoOutputs()
example(torch.ones(4,3)).sum().backward()
print([p.grad.shape for p in example.parameters()])

